function SimpleIconSvg({
	icon,
	className,
}: {
	icon: SimpleIcon;
	className?: string;
}) {
	return (
		<svg
			className={className ? className : ""}
			viewBox="0 0 24 24"
			xmlns="http://www.w3.org/2000/svg"
			role="img"
			aria-label={icon.title}
		>
			<path fill="currentColor" d={icon.path} />
		</svg>
	);
}

