// PLACEHOLDER — no confirmed real/canonical logo could be sourced for this
// skill (either no brand actually owns one, e.g. "REST" or generic "SQL", or
// the only available artwork was non-free/unlicensable, e.g. Valgrind).
// Deliberately drawn to look obviously wrong so it's easy to spot and swap
// out later.
function PlaceholderLogo({ className }: { className?: string }) {
	return (
		<svg
			className={className ? className : ""}
			viewBox="0 0 24 24"
			xmlns="http://www.w3.org/2000/svg"
			role="img"
			aria-label="Placeholder logo — needs a real icon"
		>
			<circle
				cx="12"
				cy="12"
				r="10"
				fill="none"
				stroke="currentColor"
				strokeWidth="1.5"
				strokeDasharray="3 2"
			/>
			<text
				x="12"
				y="16.5"
				textAnchor="middle"
				fontSize="13"
				fontWeight="bold"
				fill="currentColor"
				fontFamily="ui-monospace, monospace"
			>
				?
			</text>
		</svg>
	);
}

